export const eraIndex = {};
eras.forEach((e) => { eraIndex[e.id] = e; });

// Helper to keep entries compact: ev(era, year, figure, title, description, titleEs, descriptionEs)
function ev(era, year, figure, title, description, titleEs, descriptionEs) {
  return { era, year, figure, title, description, es: { title: titleEs, description: descriptionEs } };
}

