// Number events within each era by year, and build the timeline from them.
eras.forEach((era) => {
  const evs = [];
  locations.forEach((loc) => loc.events.forEach((e) => { if (e.era === era.id) evs.push(e); }));
  evs.sort((a, b) => a.year - b.year);
  evs.forEach((e, i) => { e.order = i + 1; });
});
locations.forEach((loc) => {
  loc.eras = [...new Set(loc.events.map((e) => e.era))].sort((a, b) => a - b);
  loc.events.sort((a, b) => a.year - b.year);
});

export const timeline = locations
  .flatMap((loc) => loc.events.map((e) => ({ year: e.year, era: e.era, title: e.title, es: e.es, locationId: loc.id, locationName: loc.name, locationNameEs: loc.es.name, zone: loc.zone })))
  .sort((a, b) => a.year - b.year);
